vec4 effect(vec2 uv) {
  float t = fract(uTime * 1.2);
  float beat = exp(-t * 18.0) + 0.6 * exp(-max(t - 0.18, 0.0) * 18.0) * step(0.18, t);
  vec2 u = (uv - 0.5) / (1.0 + beat * 0.08 * uAmount) + 0.5;
  vec4 c = getColor(u);
  return vec4(c.rgb + vec3(0.25, 0.0, 0.05) * beat * uAmount, c.a);
}
